from collections import Counter
class Solution:
 def frequencySort(self,nums):
  c=Counter(nums);return sorted(nums,key=lambda x:(c[x],-x))

class Solution:
 def countConsistentStrings(self,allowed,words):
  a=set(allowed);return sum(all(c in a for c in w) for w in words)

class Solution:
 def halvesAreAlike(self,s):
  v=set('aeiouAEIOU');m=len(s)//2
  return sum(c in v for c in s[:m])==sum(c in v for c in s[m:])

class Solution:
 def maximumUnits(self,boxTypes,truckSize):
  ans=0
  for boxes,units in sorted(boxTypes,key=lambda x:-x[1]):
   take=min(boxes,truckSize);ans+=take*units;truckSize-=take
   if truckSize==0:break
  return ans

class Solution:
 def decode(self,encoded,first):
  out=[first]
  for x in encoded:out.append(out[-1]^x)
  return out

class Solution:
 def largestAltitude(self,gain):
  cur=best=0
  for x in gain:cur+=x;best=max(best,cur)
  return best
